dir:

















































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',') 

	select top 0 ma_kien,so_luong,ty_trong,tong_trong,ty_khoi,tong_khoi,id as id_bg,so_ct as so_ct_bg,line as line_bg from v61 a

	select a.ma_kh ma_dt_vc , a.so_tk , a.book_no, a.id id_dh_nb, a.so_ct so_ct_nb, a.ma_ct ma_ct_nb, b.ten_kh ten_dt_vc from s61 a 
	  left join dmkh b on a.ma_kh =b.ma_kh 
	where a.id in (select top 1 id from #id order by id desc)









  &DefaultButton;




function filter$s614CRSelect(p){
  this.constructor(p);
}
filter$s614CRSelect.prototype = new DirEvent();
filter$s614CRSelect.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$s614CRSelect.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$s614CRSetMaster(p);

}

function dir$s614CRSetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$s614CRSelect.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	//dt.removeRow('[so_luong] == 0');
    //pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong');
	//pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
    p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}










					select top 1 a.ma_kh [!ma_kh],a.ma_hang [!ma_hang], a.ma_noi_di [!ma_noi_di], a.ma_noi_den [!ma_noi_den], a.ma_job [!ma_job], a.so_job [!so_job],
					b.ten_noi_di [!ten_noi_di],c.ten_noi_den [!ten_noi_den],d.ten_kh [!ten_kh],e.ten_hang [!ten_hang], a.dien_giai [!dien_giai], a.so_tk [!so_tk], a.book_no [!book_no]
				  from s61 a 
				  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
				  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
				  left join dmkh d on a.ma_kh =d.ma_kh 
				  left join vdmhangtau e on a.ma_hang =e.ma_hang 
				  where a.id = @id
